"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFeatureContent } from "./components/feature-sections/content";
import View9 from "./components/feature-sections/variants/10-steps";
const variants = {"steps":View9};
export type { ArtemisFeatureContent, ArtemisFeatureImage, ArtemisFeatureItem, ArtemisFeatureLink } from "./components/feature-sections/content";
export interface ArtemisFeatureSectionsProps { className?: string; variant?: "steps"; /** The words on the feature section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFeatureContent>; }
export function ArtemisFeatureSections({ className, variant = "steps", content }: ArtemisFeatureSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link or button, and where it goes. */
export interface ArtemisFeatureLink {
  label: string;
  href: string;
}

/** A picture shown as content, and the words that stand in for it. */
export interface ArtemisFeatureImage {
  src: string;
  alt: string;
}

/** One feature: a row, card, step or tab, depending on the layout. */
export interface ArtemisFeatureItem {
  /** The feature's name. All layouts; signal-grid puts its first word on a line of its own. */
  title: string;
  /** A sentence or two about the feature. All layouts; product-hotspots, steps, tabs and stage-tabs show it for the chosen feature only. */
  description: string;
  /** A short name: the tab in tabs and stage-tabs (which show the title when you leave this out), and the words after the number in alternating-rows. */
  label?: string;
  /** Short points under the description. alternating-rows, product-hotspots and tabs. */
  bullets?: string[];
  /** A figure shown large. voice-ai (first card) and control-deck (third and fourth cards; on the third, a trailing % is set small and fills the bar). */
  stat?: string;
  /** The feature's icon. visual-benefits, signal-grid, voice-ai (first card), control-deck (fourth and fifth cards) and tabs, which keep their own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
  /** A product picture. tabs, which shows its own picture for that slot when you leave this out. */
  image?: ArtemisFeatureImage;
}

/**
 * The words on an Artemis feature section. Every layout reads this shape, so you can switch layouts and keep them.
 * An empty `badge`, `headlineAccent` or `subhead` leaves that line out.
 */
export interface ArtemisFeatureContent {
  /** A short line above the headline. All layouts except visual-benefits, alternating-rows and stage-tabs. */
  badge?: string;
  /** The section heading. All layouts except stage-tabs. */
  headline?: string;
  /**
   * The second part of the heading. showcase, signal-grid, control-deck, voice-ai, list, bento and tabs put it on a
   * line of its own, steps sets it in the accent color, and the other layouts with a heading run it on after the
   * headline. It goes with `headline`: give a headline without it and the heading has no second part.
   */
  headlineAccent?: string;
  /** A sentence or two under the heading. All layouts except visual-benefits, tabs and stage-tabs. */
  subhead?: string;
  /**
   * The features. All layouts. Today's counts look best: three in visual-benefits, alternating-rows, showcase,
   * benefits-triptych and steps; four in product-hotspots, voice-ai, list, tabs and stage-tabs; five in control-deck
   * (which shows no more than five) and bento; six in signal-grid.
   */
  items: ArtemisFeatureItem[];
  /** The button under the features. visual-benefits. */
  cta?: ArtemisFeatureLink;
}

"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import type { ArtemisFeatureContent } from "../content";
const DEFAULT = {
    badge: "Simple by design",
    headline: "From idea to shipped UI in",
    headlineAccent: "three steps",
    subhead: "Turn a single prompt into a finished interface \u2014 compose premium blocks and own the source, all from one workflow.",
    items: [
        { title: "Describe what you need", description: "Tell Artemis the page you want in plain English \u2014 no complex setup, just your goal and brand." },
        { title: "Drop in the blocks", description: "Pick premium blocks and components; they compose into a complete, animated screen." },
        { title: "Ship the page", description: "Preview, copy the source into your repo, and publish \u2014 production-ready in minutes." },
    ],
} satisfies ArtemisFeatureContent;
const ACCENT = "#2563eb";
const ADVANCE_MS = 3800;
const REVEAL_HIDDEN = { opacity: 0, filter: "blur(6px)", y: 14 };
const REVEAL_SHOWN = { opacity: 1, filter: "blur(0px)", y: 0 };
const BUTTON_CLASS = "art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:inline-block art:h-auto art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:max-w-md art:text-left art:outline-none art:rounded-full";
function Check() {
    return (<span className="art:grid art:size-4 art:place-items-center art:rounded-full art:text-white" style={{ backgroundColor: ACCENT }}>
      <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check art:size-2.5" aria-hidden="true">
        <path d="M20 6 9 17l-5-5"/>
      </svg>
    </span>);
}
function Highlight({ children }: {
    children: string;
}) {
    return (<span className="art:rounded art:px-1" style={{ backgroundColor: `color-mix(in oklch, ${ACCENT} 18%, transparent)`, color: ACCENT }}>
      {children}
    </span>);
}
function PanelContent({ step }: {
    step: number;
}) {
    if (step === 0) {
        return (<div className="art:relative art:rounded-2xl art:border art:border-border art:bg-background art:p-5">
        <p className="art:text-foreground art:text-sm art:leading-7">
          {"Build a"}{" "}<Highlight>pricing page with a hero</Highlight>{" "}{"and a"}{" "}<Highlight>gradient CTA</Highlight>{" "}{"for my SaaS."}
        </p>
        <div className="art:mt-5 art:inline-flex art:items-center art:gap-1 art:rounded-full art:bg-neutral-900 art:p-1 art:text-white art:text-xs">
          <span className="art:rounded-full art:px-3 art:py-1.5 art:text-white/70">Generate</span>
          <span className="art:rounded-full art:bg-white/15 art:px-3 art:py-1.5">Compose</span>
        </div>
      </div>);
    }
    if (step === 1) {
        return (<div className="art:rounded-2xl art:border art:border-border art:bg-background art:p-5">
        <p className="art:font-medium art:text-foreground art:text-sm">Composing page…</p>
        <div className="art:mt-4 art:flex art:flex-col art:gap-2.5">
          {["Hero section", "Pricing block", "CTA section"].map((label) => (<div key={label} className="art:flex art:items-center art:gap-2.5 art:rounded-lg art:border art:border-border art:bg-background art:px-3 art:py-2 art:text-foreground art:text-sm">
              <Check />
              {label}
            </div>))}
        </div>
      </div>);
    }
    return (<div className="art:rounded-2xl art:border art:border-border art:bg-background art:p-5">
      <div className="art:flex art:items-center art:justify-between">
        <span className="art:font-medium art:text-foreground art:text-sm">Preview ready</span>
        <span className="art:inline-flex art:items-center art:gap-1.5 art:rounded-full art:px-2.5 art:py-1 art:font-medium art:text-white art:text-xs" style={{ backgroundColor: ACCENT }}>
          <span className="art:size-1.5 art:rounded-full art:bg-white"/> Live
        </span>
      </div>
      <div className="art:mt-4 art:space-y-2 art:rounded-xl art:border art:border-border art:bg-background art:p-3">
        <div className="art:h-2.5 art:w-1/2 art:rounded-full art:bg-foreground/15"/>
        <div className="art:h-2 art:w-4/5 art:rounded-full art:bg-foreground/10"/>
        <div className="art:h-2 art:w-2/3 art:rounded-full art:bg-foreground/10"/>
        <div className="art:mt-3 art:h-7 art:w-24 art:rounded-full" style={{ backgroundColor: ACCENT }}/>
      </div>
    </div>);
}
export default function FeatureSectionsSteps({ content }: { content?: Partial<ArtemisFeatureContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const accent = content?.headline === undefined ? copy.headlineAccent : content.headlineAccent;
    const reduce = useReducedMotion();
    const [active, setActive] = useState(0);
    const timer = useRef<ReturnType<typeof setInterval> | null>(null);
    const hovering = useRef(false);
    const count = useRef(copy.items.length);
    count.current = copy.items.length;
    const stop = () => {
        if (timer.current)
            clearInterval(timer.current);
        timer.current = null;
    };
    const restart = () => {
        stop();
        if (hovering.current)
            return;
        timer.current = setInterval(() => setActive((i) => (i + 1) % Math.max(count.current, 1)), ADVANCE_MS);
    };
    useEffect(() => {
        restart();
        return stop;
    }, []);
    const select = (i: number) => {
        setActive(i);
        restart();
    };
    const reveal = (delay: number) => ({
        initial: reduce ? false : REVEAL_HIDDEN,
        whileInView: REVEAL_SHOWN,
        viewport: { once: true },
        transition: { duration: 0.5, delay, ease: ARTEMIS_EASE_OUT },
    });
    return (<>
      <div className="art:w-full">
        <section className="art:w-full art:px-4 art:py-20 art:@min-[640px]/artemis:px-8">
          <div className="art:mx-auto art:w-full art:max-w-6xl">
            <div className="art:mx-auto art:max-w-2xl art:text-center">
              {copy.badge ? <p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-widest">{copy.badge}</p> : null}
              <motion.h2 className="art:mt-5 art:text-balance art:font-medium art:text-4xl art:text-foreground art:leading-none art:tracking-tight" {...reveal(0)}>
                {copy.headline}
                {accent ? (<>
                {" "}
                <span style={{ color: ACCENT }}>{accent}</span>
                </>) : null}
              </motion.h2>
              {copy.subhead ? (<motion.p className="art:mt-4 art:text-pretty art:text-muted-foreground art:text-sm art:leading-7 art:@min-[640px]/artemis:text-base" {...reveal(0.12)}>
                {copy.subhead}
              </motion.p>) : null}
            </div>
            <div className="art:mt-14 art:grid art:items-center art:gap-10 art:@min-[1024px]/artemis:grid-cols-2 art:@min-[1024px]/artemis:gap-14">
              <div className="art:flex art:flex-col art:gap-6">
                {copy.items.map((s, i) => {
            const on = i === active;
            const n = String(i + 1).padStart(2, "0");
            return (<motion.button key={n} type="button" className={BUTTON_CLASS} tabIndex={0} whileHover={reduce ? undefined : { scale: 1.01 }} onMouseEnter={() => {
                    hovering.current = true;
                    select(i);
                }} onMouseLeave={() => {
                    hovering.current = false;
                    restart();
                }} onClick={() => select(i)}>
                      <span className="art:font-medium art:font-mono art:text-sm art:transition-colors" style={on ? { color: ACCENT } : undefined}>
                        <span className={on ? " " : "art:text-muted-foreground/50"}>{n}</span>
                      </span>
                      <h3 className={`art:mt-1 art:font-medium art:text-xl art:transition-colors ${on ? "art:text-foreground" : "art:text-muted-foreground/60"}`}>{s.title}</h3>
                      <AnimatePresence initial={false}>
                        {on && (<motion.p key="body" className="art:overflow-hidden art:text-muted-foreground art:text-sm art:leading-7" initial={{ height: 0, opacity: 0, marginTop: 0 }} animate={{ height: "auto", opacity: 1, marginTop: 8 }} exit={{ height: 0, opacity: 0, marginTop: 0 }} transition={{ duration: 0.32, ease: ARTEMIS_EASE_OUT }}>
                            {s.description}
                          </motion.p>)}
                      </AnimatePresence>
                    </motion.button>);
        })}
              </div>
              <div className="art:relative art:h-[24rem] art:overflow-hidden art:rounded-2xl art:border art:border-border/60 art:bg-background">
                <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0 art:overflow-hidden">

                  <img src="/assets/artemis/0cc0d1493e54673aa1e7.webp" alt="" width="768" height="768" loading="lazy" decoding="async" className="art:size-full art:object-cover" style={{ objectPosition: "center" }}/>
                  <div className="art:absolute art:inset-0 art:bg-background/10 art:dark:bg-background/65"/>
                </div>
                <div className="art:absolute art:inset-0 art:grid art:place-items-center art:p-6">
                  <AnimatePresence mode="wait" initial={false}>
                    <motion.div key={active} className="art:w-full art:max-w-sm" initial={{ opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} transition={{ duration: 0.3, ease: ARTEMIS_EASE_OUT }}>
                      <PanelContent step={active % 3}/>
                    </motion.div>
                  </AnimatePresence>
                </div>
              </div>
            </div>
          </div>
        </section>
      </div>
    </>);
}
